   127  // Returns whether the class can handle the format of the given file.
   128  bool DXFImporter::CanRead( const std::string& filename, IOSystem* pIOHandler, bool checkSig ) const {
   129      const std::string& extension = GetExtension( filename );
   130      if ( extension == desc.mFileExtensions ) {
   131          return true;
   132      }
   133
   134      if ( extension.empty() || checkSig ) {
   135          const char *pTokens[] = { "SECTION", "HEADER", "ENDSEC", "BLOCKS" };
   136          return BaseImporter::SearchFileHeaderForToken(pIOHandler, filename, pTokens, 4, 32 );
   137      }
   138
   139      return false;
   140  }
