   148  // ------------------------------------------------------------------------------------------------
   149  // Imports the given file into the given scene structure.
   150  void DXFImporter::InternReadFile( const std::string& filename, aiScene* pScene, IOSystem* pIOHandler) {
   151      std::shared_ptr<IOStream> file = std::shared_ptr<IOStream>( pIOHandler->Open( filename) );
   152
   153      // Check whether we can read the file
   154      if( file.get() == nullptr ) {
   155          throw DeadlyImportError( "Failed to open DXF file ", filename, "");
   156      }
   157
   158      // Check whether this is a binary DXF file - we can't read binary DXF files :-(
   159      char buff[AI_DXF_BINARY_IDENT_LEN+1] = {0};
   160      file->Read(buff,AI_DXF_BINARY_IDENT_LEN,1);
   161
   162      if (0 == strncmp(AI_DXF_BINARY_IDENT.c_str(),buff,AI_DXF_BINARY_IDENT_LEN)) {
   163          throw DeadlyImportError("DXF: Binary files are not supported at the moment");
   164      }
   165
   166      // DXF files can grow very large, so read them via the StreamReader,
   167      // which will choose a suitable strategy.
   168      file->Seek(0,aiOrigin_SET);
   169      StreamReaderLE stream( file );
   170
   171      DXF::LineReader reader (stream);
   172      DXF::FileData output;
   173
   174      // now get all lines of the file and process top-level sections
   175      bool eof = false;
   176      while(!reader.End()) {
   177
   178          // blocks table - these 'build blocks' are later (in ENTITIES)
   179          // referenced an included via INSERT statements.
   180          if (reader.Is(2,"BLOCKS")) {
   181              ParseBlocks(reader,output);
   182              continue;
   183          }
   184
   185          // primary entity table
   186          if (reader.Is(2,"ENTITIES")) {
   187              ParseEntities(reader,output);
   188              continue;
   189          }
   190
   191          // skip unneeded sections entirely to avoid any problems with them
   192          // altogether.
   193          else if (reader.Is(2,"CLASSES") || reader.Is(2,"TABLES")) {
   194              SkipSection(reader);
   195              continue;
   196          }
   197
   198          else if (reader.Is(2,"HEADER")) {
   199              ParseHeader(reader,output);
   200              continue;
   201          }
   202
   203          // comments
   204          else if (reader.Is(999)) {
   205              ASSIMP_LOG_INFO_F("DXF Comment: ", reader.Value());
   206          }
   207
   208          // don't read past the official EOF sign
   209          else if (reader.Is(0,"EOF")) {
   210              eof = true;
   211              break;
   212          }
   213
   214          ++reader;
   215      }
   216      if (!eof) {
   217          ASSIMP_LOG_WARN("DXF: EOF reached, but did not encounter DXF EOF marker");
   218      }
   219
   220      ConvertMeshes(pScene,output);
   221
   222      // Now rotate the whole scene by 90 degrees around the x axis to convert from AutoCAD's to Assimp's coordinate system
   223      pScene->mRootNode->mTransformation = aiMatrix4x4(
   224          1.f,0.f,0.f,0.f,
   225          0.f,0.f,1.f,0.f,
   226          0.f,-1.f,0.f,0.f,
   227          0.f,0.f,0.f,1.f) * pScene->mRootNode->mTransformation;
   228  }
