   230  // ------------------------------------------------------------------------------------------------
   231  void DXFImporter::ConvertMeshes(aiScene* pScene, DXF::FileData& output) {
   232      // the process of resolving all the INSERT statements can grow the
   233      // poly-count excessively, so log the original number.
   234      // XXX Option to import blocks as separate nodes?
   235      if (!DefaultLogger::isNullLogger()) {
   236          unsigned int vcount = 0, icount = 0;
   237          for (const DXF::Block& bl : output.blocks) {
   238              for (std::shared_ptr<const DXF::PolyLine> pl : bl.lines) {
   239                  vcount += static_cast<unsigned int>(pl->positions.size());
   240                  icount += static_cast<unsigned int>(pl->counts.size());
   241              }
   242          }
   243
   244          ASSIMP_LOG_VERBOSE_DEBUG_F("DXF: Unexpanded polycount is ", icount, ", vertex count is ", vcount);
   245      }
   246
   247      if (! output.blocks.size()  ) {
   248          throw DeadlyImportError("DXF: no data blocks loaded");
   249      }
   250
   251      DXF::Block* entities( nullptr );
   252
   253      // index blocks by name
   254      DXF::BlockMap blocks_by_name;
   255      for (DXF::Block& bl : output.blocks) {
   256          blocks_by_name[bl.name] = &bl;
   257          if ( !entities && bl.name == AI_DXF_ENTITIES_MAGIC_BLOCK ) {
   258              entities = &bl;
   259          }
   260      }
   261
   262      if (!entities) {
   263          throw DeadlyImportError("DXF: no ENTITIES data block loaded");
   264      }
   265
   266      typedef std::map<std::string, unsigned int> LayerMap;
   267
   268      LayerMap layers;
   269      std::vector< std::vector< const DXF::PolyLine*> > corr;
   270
   271      // now expand all block references in the primary ENTITIES block
   272      // XXX this involves heavy memory copying, consider a faster solution for future versions.
   273      ExpandBlockReferences(*entities,blocks_by_name);
   274
   275      unsigned int cur = 0;
   276      for (std::shared_ptr<const DXF::PolyLine> pl : entities->lines) {
   277          if (pl->positions.size()) {
   278
   279              std::map<std::string, unsigned int>::iterator it = layers.find(pl->layer);
   280              if (it == layers.end()) {
   281                  ++pScene->mNumMeshes;
   282
   283                  layers[pl->layer] = cur++;
   284
   285                  std::vector< const DXF::PolyLine* > pv;
   286                  pv.push_back(&*pl);
   287
   288                  corr.push_back(pv);
   289              }
   290              else {
   291                  corr[(*it).second].push_back(&*pl);
   292              }
   293          }
   294      }
   295
   296      if ( 0 == pScene->mNumMeshes) {
   297          throw DeadlyImportError("DXF: this file contains no 3d data");
   298      }
   299
   300      pScene->mMeshes = new aiMesh*[ pScene->mNumMeshes ] ();
   301
   302      for(const LayerMap::value_type& elem : layers){
   303          aiMesh* const mesh =  pScene->mMeshes[elem.second] = new aiMesh();
   304          mesh->mName.Set(elem.first);
   305
   306          unsigned int cvert = 0,cface = 0;
   307          for(const DXF::PolyLine* pl : corr[elem.second]){
   308              // sum over all faces since we need to 'verbosify' them.
   309              cvert += std::accumulate(pl->counts.begin(),pl->counts.end(),0);
   310              cface += static_cast<unsigned int>(pl->counts.size());
   311          }
   312
   313          aiVector3D* verts = mesh->mVertices = new aiVector3D[cvert];
   314          aiColor4D* colors = mesh->mColors[0] = new aiColor4D[cvert];
   315          aiFace* faces = mesh->mFaces = new aiFace[cface];
   316
   317          mesh->mNumVertices = cvert;
   318          mesh->mNumFaces = cface;
   319
   320          unsigned int prims = 0;
   321          unsigned int overall_indices = 0;
   322          for(const DXF::PolyLine* pl : corr[elem.second]){
   323
   324              std::vector<unsigned int>::const_iterator it = pl->indices.begin();
   325              for(unsigned int facenumv : pl->counts) {
   326                  aiFace& face = *faces++;
   327                  face.mIndices = new unsigned int[face.mNumIndices = facenumv];
   328
   329                  for (unsigned int i = 0; i < facenumv; ++i) {
   330                      face.mIndices[i] = overall_indices++;
   331
   332                      ai_assert(pl->positions.size() == pl->colors.size());
   333                      if (*it >= pl->positions.size()) {
   334                          throw DeadlyImportError("DXF: vertex index out of bounds");
   335                      }
   336
   337                      *verts++ = pl->positions[*it];
   338                      *colors++ = pl->colors[*it++];
   339                  }
   340
   341                  // set primitive flags now, this saves the extra pass in ScenePreprocessor.
   342                  switch(face.mNumIndices) {
   343                      case 1:
   344                          prims |= aiPrimitiveType_POINT;
   345                          break;
   346                      case 2:
   347                          prims |= aiPrimitiveType_LINE;
   348                          break;
   349                      case 3:
   350                          prims |= aiPrimitiveType_TRIANGLE;
   351                          break;
   352                      default:
   353                          prims |= aiPrimitiveType_POLYGON;
   354                          break;
   355                  }
   356              }
   357          }
   358
   359          mesh->mPrimitiveTypes = prims;
   360          mesh->mMaterialIndex = 0;
   361      }
   362
   363      GenerateHierarchy(pScene,output);
   364      GenerateMaterials(pScene,output);
   365  }
