   368  // ------------------------------------------------------------------------------------------------
   369  void DXFImporter::ExpandBlockReferences(DXF::Block& bl,const DXF::BlockMap& blocks_by_name) {
   370      for (const DXF::InsertBlock& insert : bl.insertions) {
   371
   372          // first check if the referenced blocks exists ...
   373          const DXF::BlockMap::const_iterator it = blocks_by_name.find(insert.name);
   374          if (it == blocks_by_name.end()) {
   375              ASSIMP_LOG_ERROR_F("DXF: Failed to resolve block reference: ", insert.name,"; skipping" );
   376              continue;
   377          }
   378
   379          // XXX this would be the place to implement recursive expansion if needed.
   380          const DXF::Block& bl_src = *(*it).second;
   381
   382          for (std::shared_ptr<const DXF::PolyLine> pl_in : bl_src.lines) {
   383              std::shared_ptr<DXF::PolyLine> pl_out = std::shared_ptr<DXF::PolyLine>(new DXF::PolyLine(*pl_in));
   384
   385              if (bl_src.base.Length() || insert.scale.x!=1.f || insert.scale.y!=1.f || insert.scale.z!=1.f || insert.angle || insert.pos.Length()) {
   386                  // manual coordinate system transformation
   387                  // XXX order
   388                  aiMatrix4x4 trafo, tmp;
   389                  aiMatrix4x4::Translation(-bl_src.base,trafo);
   390                  trafo *= aiMatrix4x4::Scaling(insert.scale,tmp);
   391                  trafo *= aiMatrix4x4::Translation(insert.pos,tmp);
   392
   393                  // XXX rotation currently ignored - I didn't find an appropriate sample model.
   394                  if (insert.angle != 0.f) {
   395                      ASSIMP_LOG_WARN("DXF: BLOCK rotation not currently implemented");
   396                  }
   397
   398                  for (aiVector3D& v : pl_out->positions) {
   399                      v *= trafo;
   400                  }
   401              }
   402
   403              bl.lines.push_back(pl_out);
   404          }
   405      }
   406  }
