   408  // ------------------------------------------------------------------------------------------------
   409  void DXFImporter::GenerateMaterials(aiScene* pScene, DXF::FileData& /*output*/) {
   410      // generate an almost-white default material. Reason:
   411      // the default vertex color is GREY, so we are
   412      // already at Assimp's usual default color.
   413      // generate a default material
   414      aiMaterial* pcMat = new aiMaterial();
   415      aiString s;
   416      s.Set(AI_DEFAULT_MATERIAL_NAME);
   417      pcMat->AddProperty(&s, AI_MATKEY_NAME);
   418
   419      aiColor4D clrDiffuse(0.9f,0.9f,0.9f,1.0f);
   420      pcMat->AddProperty(&clrDiffuse,1,AI_MATKEY_COLOR_DIFFUSE);
   421
   422      clrDiffuse = aiColor4D(1.0f,1.0f,1.0f,1.0f);
   423      pcMat->AddProperty(&clrDiffuse,1,AI_MATKEY_COLOR_SPECULAR);
   424
   425      clrDiffuse = aiColor4D(0.05f,0.05f,0.05f,1.0f);
   426      pcMat->AddProperty(&clrDiffuse,1,AI_MATKEY_COLOR_AMBIENT);
   427
   428      pScene->mNumMaterials = 1;
   429      pScene->mMaterials = new aiMaterial*[1];
   430      pScene->mMaterials[0] = pcMat;
   431  }
