   433  // ------------------------------------------------------------------------------------------------
   434  void DXFImporter::GenerateHierarchy(aiScene* pScene, DXF::FileData& /*output*/) {
   435      // generate the output scene graph, which is just the root node with a single child for each layer.
   436      pScene->mRootNode = new aiNode();
   437      pScene->mRootNode->mName.Set("<DXF_ROOT>");
   438
   439      if (1 == pScene->mNumMeshes)    {
   440          pScene->mRootNode->mMeshes = new unsigned int[ pScene->mRootNode->mNumMeshes = 1 ];
   441          pScene->mRootNode->mMeshes[0] = 0;
   442      } else {
   443          pScene->mRootNode->mChildren = new aiNode*[ pScene->mRootNode->mNumChildren = pScene->mNumMeshes ];
   444          for (unsigned int m = 0; m < pScene->mRootNode->mNumChildren;++m)   {
   445              aiNode* p = pScene->mRootNode->mChildren[m] = new aiNode();
   446              p->mName = pScene->mMeshes[m]->mName;
   447
   448              p->mMeshes = new unsigned int[p->mNumMeshes = 1];
   449              p->mMeshes[0] = m;
   450              p->mParent = pScene->mRootNode;
   451          }
   452      }
   453  }
